/**
 * Optional market fields are absent when reference data is unavailable.
 * @returns {Promise<Record<string, unknown> & {available: boolean}>}
 */
async function buildMarketReference(data, parsed, scope, supplyInfo) {
  const tenderDate = tenderAnnouncementDate(data);
  if (!tenderDate) return {
    available: false,
    note: "Не вдалося підтвердити дату оприлюднення для порівняння бюджету з ринком."
  };

  const now = new Date();
  const daysOld = Math.max(0, (now.getTime() - tenderDate.getTime()) / 86400000);
  const recentTender = daysOld <= 30;
  const benchmarkDate = new Date(euro5ObservationDate(tenderDate)+"T12:00:00Z");
  const currentRetailBenchmark=euro5ObservationDate(benchmarkDate)===euro5ObservationDate(now);
  const trendDate = recentTender ? now : tenderDate;
  const pastDate = new Date(trendDate.getTime() - 30 * 86400000);

  const fuelType = parsed?.fuel_type;
  const gasVol = Number(parsed?.gasoline_volume_l);
  const dieselVol = Number(parsed?.diesel_volume_l);

  const needGas = fuelType === "gasoline" || fuelType === "mixed";
  const needDiesel = fuelType === "diesel" || fuelType === "mixed";

  const retailContext=await loadEuro5RetailContext(currentRetailBenchmark);
  const [retailGas, retailDiesel, trendGas, trendGasPast, trendDiesel, trendDieselPast, enkorr] = await Promise.all([
    needGas ? fetchRetailPrice("a95", benchmarkDate, retailContext) : null,
    needDiesel ? fetchRetailPrice("dt", benchmarkDate, retailContext) : null,
    needGas ? fetchMinfinPrice("a95", trendDate) : null,
    needGas ? fetchMinfinPrice("a95", pastDate) : null,
    needDiesel ? fetchMinfinPrice("dt", trendDate) : null,
    needDiesel ? fetchMinfinPrice("dt", pastDate) : null,
    fetchEnkorrCurrentPrices()
  ]);

  // Enkorr must be dated on or before the announcement, at most five
  // business days earlier. Never use future prices for historical comparison.
  let enkorrMinfinGas = null, enkorrMinfinDiesel = null;
  if (enkorr?.date) {
    [enkorrMinfinGas, enkorrMinfinDiesel] = await Promise.all([
      enkorr?.gasoline ? fetchMinfinPrice("a95", enkorr.date) : null,
      enkorr?.diesel ? fetchMinfinPrice("dt", enkorr.date) : null
    ]);
  }

  const crossGas = percentDifference(enkorr?.gasoline?.retail, enkorrMinfinGas?.priceWithVat);
  const crossDiesel = percentDifference(enkorr?.diesel?.retail, enkorrMinfinDiesel?.priceWithVat);
  const crossCheckLimitPct = 5;
  const gasWholesaleParsedOk = !!enkorr?.gasoline?.wholesale && (crossGas === null || crossGas <= crossCheckLimitPct);
  const dieselWholesaleParsedOk = !!enkorr?.diesel?.wholesale && (crossDiesel === null || crossDiesel <= crossCheckLimitPct);
  const wholesaleDateGap = enkorr?.date ? wholesaleBenchmarkAge(tenderDate, enkorr.date) : null;
  const wholesaleRecentEnough = wholesaleDateGap !== null && wholesaleDateGap <= 5;

  const retailGasNoVat = retailGas?.priceWithoutVat ?? null;
  const retailDieselNoVat = retailDiesel?.priceWithoutVat ?? null;
  const wholesaleGasNoVat = gasWholesaleParsedOk ? enkorr.gasoline.wholesale / (1 + UKRAINE_STANDARD_VAT) : null;
  const wholesaleDieselNoVat = dieselWholesaleParsedOk ? enkorr.diesel.wholesale / (1 + UKRAINE_STANDARD_VAT) : null;
  const gasWholesaleUsable = !!wholesaleRecentEnough && !!wholesaleGasNoVat;
  const dieselWholesaleUsable = !!wholesaleRecentEnough && !!wholesaleDieselNoVat;

  const globalFormat = normalizeSupplyFormat(supplyInfo?.supplyFormat);
  const gasFormat = globalFormat === "split" ? normalizeSupplyFormat(supplyInfo?.gasolineSupplyFormat) : globalFormat;
  const dieselFormat = globalFormat === "split" ? normalizeSupplyFormat(supplyInfo?.dieselSupplyFormat) : globalFormat;

  const gasSelected = chooseMarketPrice(gasFormat, retailGasNoVat, wholesaleGasNoVat, gasWholesaleUsable);
  const dieselSelected = chooseMarketPrice(dieselFormat, retailDieselNoVat, wholesaleDieselNoVat, dieselWholesaleUsable);

  let marketValue = null;
  if (fuelType === "gasoline" && gasVol > 0 && gasSelected > 0) {
    marketValue = gasVol * gasSelected;
  } else if (fuelType === "diesel" && dieselVol > 0 && dieselSelected > 0) {
    marketValue = dieselVol * dieselSelected;
  } else if (fuelType === "mixed" && gasVol > 0 && dieselVol > 0 && gasSelected > 0 && dieselSelected > 0) {
    marketValue = gasVol * gasSelected + dieselVol * dieselSelected;
  }

  // Trend uses Minfin at both dates. EURO5 is only the retail price level.
  const trendGasNoVat=trendGas?.priceWithoutVat??null,trendDieselNoVat=trendDiesel?.priceWithoutVat??null;
  let currentTrendValue = null;
  let pastTrendValue = null;
  if (fuelType === "gasoline" && gasVol > 0 && trendGasNoVat > 0) {
    currentTrendValue = gasVol * trendGasNoVat;
    if (trendGasPast?.priceWithoutVat > 0) pastTrendValue = gasVol * trendGasPast.priceWithoutVat;
  } else if (fuelType === "diesel" && dieselVol > 0 && trendDieselNoVat > 0) {
    currentTrendValue = dieselVol * trendDieselNoVat;
    if (trendDieselPast?.priceWithoutVat > 0) pastTrendValue = dieselVol * trendDieselPast.priceWithoutVat;
  } else if (fuelType === "mixed" && gasVol > 0 && dieselVol > 0 && trendGasNoVat > 0 && trendDieselNoVat > 0) {
    currentTrendValue = gasVol * trendGasNoVat + dieselVol * trendDieselNoVat;
    if (trendGasPast?.priceWithoutVat > 0 && trendDieselPast?.priceWithoutVat > 0) {
      pastTrendValue = gasVol * trendGasPast.priceWithoutVat + dieselVol * trendDieselPast.priceWithoutVat;
    }
  }

  const fuelTrend30dPct = currentTrendValue > 0 && pastTrendValue > 0
    ? (currentTrendValue / pastTrendValue - 1) * 100
    : null;

  const crossNotes = [];
  if (enkorr?.gasoline && crossGas !== null) crossNotes.push(`А-95: роздріб Enkorr vs Minfin ${crossGas.toFixed(1)}%`);
  if (enkorr?.diesel && crossDiesel !== null) crossNotes.push(`ДП: роздріб Enkorr vs Minfin ${crossDiesel.toFixed(1)}%`);

  const benchmarkLabel = globalFormat === "bulk"
    ? "оптовий ринок Enkorr"
    : globalFormat === "retail"
      ? [retailGas?.source, retailDiesel?.source].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(" / ") || "роздрібний орієнтир на дату оголошення недоступний"
      : globalFormat === "split"
        ? "окремий ринковий орієнтир для кожної позиції"
        : "не визначено";

  const common = {
    available: marketValue > 0,
    benchmarkType: globalFormat,
    benchmarkLabel,
    benchmarkContext: globalFormat === "bulk" ? (recentTender ? "current" : "historical") : (currentRetailBenchmark ? "current" : "historical"),
    tenderDate: formatUaDate(tenderDate),
    retailReferenceDate: retailGas?.date || retailDiesel?.date || null,
    retailSource: [retailGas?.source,retailDiesel?.source].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(' / ') || null,
    retailGasolineSource: retailGas?.source || null,
    retailDieselSource: retailDiesel?.source || null,
    fuelTrendNote: 'Тренд розраховано за роздрібними цінами Minfin / Консалтингової групи А-95 на обидві дати.',
    trendEndDate: trendGas?.date || trendDiesel?.date || null,

    wholesaleReferenceDate: enkorr?.date ? formatUaDate(enkorr.date) : null,
    retailGasolinePriceWithoutVat: retailGasNoVat,
    retailDieselPriceWithoutVat: retailDieselNoVat,
    wholesaleGasolinePriceWithoutVat: wholesaleGasNoVat,
    wholesaleDieselPriceWithoutVat: wholesaleDieselNoVat,
    wholesaleGasolineUsable: gasWholesaleUsable,
    wholesaleDieselUsable: dieselWholesaleUsable,
    wholesaleCrosscheckNote: crossNotes.join("; ") || null,
    fuelTrend30dPct,
    trendStartDate: trendGasPast?.date || trendDieselPast?.date || formatUaDate(pastDate)
  };

  if (!(marketValue > 0)) {
    let note;
    if (globalFormat === "unknown") {
      note = "Формат постачання не визначено. Оберіть «Налив» або «Талони / паливні картки», щоб розрахувати бюджет замовника до ринку.";
    } else if (!recentTender && (globalFormat === "bulk" || gasFormat === "bulk" || dieselFormat === "bulk")) {
      note = "Гуртовий орієнтир Enkorr на дату оголошення або не більш ніж за 5 робочих діб до неї недоступний. Пізніші ціни не використовуються. Порівняння не розраховано; у рейтингу — нейтральні 10/20 балів.";
    } else if ((gasFormat === "bulk" && !gasWholesaleUsable) || (dieselFormat === "bulk" && !dieselWholesaleUsable)) {
      note = "Немає підтвердженої гуртової ціни Enkorr на дату оголошення або не більш ніж за 5 робочих діб до неї. Пізніші ціни не використовуються. Порівняння не розраховано; у рейтингу — нейтральні 10/20 балів.";
    } else {
      note = "Ринковий орієнтир знайдено не для всіх потрібних позицій або немає підтвердженого обсягу.";
    }
    return { ...common, note };
  }

  const gap = (scope.normalizedWithoutVat / marketValue - 1) * 100;
  const abs = Math.abs(gap).toLocaleString("uk-UA", { maximumFractionDigits: 2 });
  const text = Math.abs(gap) < 0.05
    ? "Очікувана вартість практично відповідає ринковій вартості такого обсягу."
    : `Очікувана вартість на ${abs}% ${gap > 0 ? "вища" : "нижча"} за ринкову вартість такого обсягу.`;

  return {
    ...common,
    marketValueWithoutVat: marketValue,
    budgetVsMarketPct: gap,
    text,
    referenceDate: globalFormat === "bulk" ? common.wholesaleReferenceDate : common.retailReferenceDate,
    note: globalFormat === "bulk"
      ? "Для наливу використано гуртовий орієнтир Enkorr на дату оголошення або не більш ніж за 5 робочих діб до неї (понеділок–п’ятниця). Пізніші ціни виключені. Роздрібну колонку Enkorr звірено з Minfin як контроль правильності даних."
      : globalFormat === "retail"
        ? "Для талонів / паливних карток використано: "+common.retailSource+". Порівняння на дату оголошення: спочатку стела або архів Євро5 за потрібну дату; за відсутності ціни відповідної позиції — щоденні ціни Minfin."
        : "Для кожної позиції використано орієнтир відповідно до підтвердженого формату постачання."
  };
}

function nbuDateKey(date) {
  return `${date.getUTCFullYear()}${String(date.getUTCMonth()+1).padStart(2,"0")}${String(date.getUTCDate()).padStart(2,"0")}`;
}

async function fetchNbuUsdRate(targetDate) {
  if (!(targetDate instanceof Date) || Number.isNaN(targetDate.getTime())) return null;
  for (let back = 0; back <= 7; back++) {
    const d = new Date(targetDate.getTime() - back * 86400000);
    const url = `https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?valcode=USD&date=${nbuDateKey(d)}&json`;
    try {
      const res = await fetch(url, { headers: { "Accept": "application/json" } });
      if (!res.ok) continue;
      const payload = await res.json();
      const row = Array.isArray(payload) ? payload.find(x => x?.cc === "USD") || payload[0] : null;
      const rate = Number(row?.rate);
      if (Number.isFinite(rate) && rate > 0) return { rate, date: formatUaDate(d), source: "НБУ" };
    } catch (_) {}
  }
  return null;
}

async function fetchPriceRiskHistory(targetDate){
  try{
    const res=await fetch('https://raw.githubusercontent.com/ukrsedo/euro5-tender-bid-assistant/main/data/market-series.json',{signal:AbortSignal.timeout(15000)});
    if(!res.ok)return {ready:false,reason:'Не вдалося отримати історичний ряд цін.'};
    const data=await res.json(),asOf=euro5ObservationDate(targetDate);
    if(data.schema_version!==1||!Array.isArray(data.records))return {ready:false,reason:'Некоректний ряд цін.'};
    return {ready:true,as_of:asOf,updated_at:data.updated_at,sources:data.sources,records:data.records.filter(r=>r.date<=asOf)};
  }catch(_){return {ready:false,reason:'Історичний ряд цін тимчасово недоступний.'}}
}

async function buildFxTrend(data) {
  const date = tenderAnnouncementDate(data);
  if (!date) return { available: false, note: "Не вдалося визначити дату для валютного тренду." };
  const pastDate = new Date(date.getTime() - 30 * 86400000);
  const [current, past] = await Promise.all([fetchNbuUsdRate(date), fetchNbuUsdRate(pastDate)]);
  if (!current || !past) return { available: false, note: "Не вдалося завантажити курс USD/UAH для 30-денного порівняння." };
  const change30dPct = (current.rate / past.rate - 1) * 100;
  return {
    available: true,
    currentDate: current.date,
    pastDate: past.date,
    change30dPct,
    note: "Валютний фактор розраховано за офіційним курсом USD/UAH НБУ."
  };
}

function validateScope(data) {
  const cpvCodes = collectCpvCodes(data);
  const allowedFound = cpvCodes.filter(code => ALLOWED_CPV.has(code) || /^09132/.test(code) || /^09134/.test(code));
  const expected = getExpectedValue(data);

  if (!cpvCodes.length) {
    return {
      ok: false,
      reason: "CPV_NOT_FOUND",
      message: "У даних Prozorro не знайдено CPV. Не вдалося автоматично перевірити, чи підходить тендер для цієї моделі.",
      cpvCodes,
      expected
    };
  }

  if (!allowedFound.length) {
    return {
      ok: false,
      reason: "CPV_OUT_OF_SCOPE",
      message: `CPV ${cpvCodes.join(", ")} не належить до паливних кодів, для яких розрахована ця модель.`,
      cpvCodes,
      expected
    };
  }

  if (!expected.amount) {
    return {
      ok: false,
      reason: "VALUE_NOT_FOUND",
      message: "У даних Prozorro не знайдено очікувану вартість. Розрахунок неможливий.",
      cpvCodes,
      allowedFound,
      expected
    };
  }

  let normalizedWithoutVat;
  let normalizationNote;

  if (expected.vatIncluded === false) {
    normalizedWithoutVat = expected.amount;
    normalizationNote = "Prozorro вказує очікувану вартість без ПДВ; сума використовується без перерахунку.";
  } else if (expected.vatIncluded === true) {
    normalizedWithoutVat = expected.amount / (1 + UKRAINE_STANDARD_VAT);
    normalizationNote = "Prozorro вказує очікувану вартість з ПДВ; суму перераховано без ПДВ за ставкою 20%. Користувач має перевірити суму перед розрахунком.";
  } else {
    return {
      ok: false,
      reason: "VAT_BASIS_UNKNOWN",
      message: "Очікувану вартість знайдено, але Prozorro не повернув однозначну ознаку ПДВ. Для розрахунку потрібна сума без ПДВ.",
      cpvCodes,
      allowedFound,
      expected
    };
  }

  if (normalizedWithoutVat < 1000000) {
    return {
      ok: false,
      reason: "VALUE_OUT_OF_SCOPE",
      message: `Очікувана вартість для розрахунку становить ${Math.round(normalizedWithoutVat).toLocaleString("uk-UA")} грн без ПДВ, тобто менше 1 млн грн. Такий тендер не входить до сфери застосування моделі.`,
      cpvCodes,
      allowedFound,
      expected,
      normalizedWithoutVat,
      normalizationNote
    };
  }

  return {
    ok: true,
    reason: "ELIGIBLE",
    message: "CPV і очікувана вартість відповідають сфері застосування моделі.",
    cpvCodes,
    allowedFound,
    primaryCpv: allowedFound[0],
    expected,
    normalizedWithoutVat,
    normalizationNote
  };
}

function aiTenderPayload(data) {
  const announcement=tenderAnnouncementDate(data);
  const cutoff=announcement?euro5ObservationDate(announcement):null;
  const prospectiveDocuments=(data?.documents||[]).filter(d=>{
    const published=new Date(d?.datePublished),modified=new Date(d?.dateModified||d?.datePublished);
    return cutoff&&Number.isFinite(published.getTime())&&Number.isFinite(modified.getTime())&&euro5ObservationDate(published)<=cutoff&&euro5ObservationDate(modified)<=cutoff;
  });
  const reduced = {
    tenderID: data?.tenderID,
    title: data?.title,
    description: data?.description,
    procurementMethodType: data?.procurementMethodType,
    value: data?.value,
    items: data?.items,
    lots: (data?.lots||[]).map(({id,title,description,value})=>({id,title,description,value})),
    documents: prospectiveDocuments.map(d => ({
      title: d?.title,
      documentType: d?.documentType,
      format: d?.format,
      url: d?.url,
      datePublished: d?.datePublished
    })),
    tenderPeriod: data?.tenderPeriod,
    enquiryPeriod: data?.enquiryPeriod,
    guarantee: data?.guarantee,
    criteria: data?.criteria,
    features: data?.features,
    milestones: data?.milestones
  };

  let s = JSON.stringify(reduced);
  if (s.length > 70000) s = s.slice(0, 70000);
  return s;
}

